static uint32_t mc_get_utf8_codepoint_length(const char *buf, uint32_t len) {
    BSON_ASSERT_PARAM(buf);
    const char *cur = buf;
    const char *end = buf + len;
    uint32_t codepoint_len = 0;
    while (cur < end) {
        cur = bson_utf8_next_char(cur);
        codepoint_len++;
