++    //     maxkgram_1 = sum_(j=lb, ub, (mlen - j + 1))          # as above
++    //     maxkgram_2 = sum_(j=lb, ub, (cbclen - j + 1))        # same sum bounds as maxkgram_1
++    //     msize      = sum_(j=lb, ub, (min(mlen, cbclen) - j + 1))
